import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { vendorService } from '../../services/vendorService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage } from '../../utils/helpers';

const VendorDetails = () => {
  const [vendor, setVendor] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { id } = useParams();
  const navigate = useNavigate();

  useEffect(() => {
    loadVendorDetails();
  }, [id]);

  const loadVendorDetails = async () => {
    try {
      setLoading(true);
      setError('');
      
      // Since we don't have a specific endpoint for vendor details,
      // we'll get all vendors and find the one we need
      const response = await vendorService.getAllPublicVendors();
      const vendorData = response.data.find(v => v.id.toString() === id);
      
      if (vendorData) {
        setVendor(vendorData);
      } else {
        setError('Food truck not found');
      }
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LoadingSpinner message="Loading food truck details..." />;
  }

  if (error) {
    return (
      <div className="vendor-details-page">
        <div className="container">
          <div className="error-container">
            <div className="error-message">
              <h2>Error Loading Details</h2>
              <p>{error}</p>
              <div className="error-actions">
                <button onClick={loadVendorDetails} className="btn btn-primary">
                  Try Again
                </button>
                <button onClick={() => navigate('/vendors')} className="btn btn-outline">
                  Back to Vendors
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!vendor) {
    return (
      <div className="vendor-details-page">
        <div className="container">
          <div className="not-found">
            <h2>Food Truck Not Found</h2>
            <p>The food truck you're looking for doesn't exist or has been removed.</p>
            <button onClick={() => navigate('/vendors')} className="btn btn-primary">
              Back to All Vendors
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="vendor-details-page">
      <div className="container">
        <div className="back-navigation">
          <button onClick={() => navigate('/vendors')} className="back-btn">
            ← Back to All Vendors
          </button>
        </div>

        <div className="vendor-details-card">
          <div className="vendor-header">
            <h1>{vendor.name}</h1>
            <div className="vendor-meta">
              <span className="region">📍 {vendor.operatingRegion}</span>
            </div>
          </div>

          <div className="vendor-content">
            <div className="info-section">
              <h3>Cuisine Specialties</h3>
              <p className="cuisine-tags">
                {vendor.cuisineSpecialties && vendor.cuisineSpecialties.split(',').map((cuisine, index) => (
                  <span key={index} className="cuisine-tag">
                    {cuisine.trim()}
                  </span>
                ))}
              </p>
            </div>

            {vendor.menuHighlights && (
              <div className="info-section">
                <h3>Menu Highlights</h3>
                <p>{vendor.menuHighlights}</p>
              </div>
            )}

            {vendor.businessAddress && (
              <div className="info-section">
                <h3>Address</h3>
                <p>📍 {vendor.businessAddress}</p>
              </div>
            )}

            {vendor.phoneNumber && (
              <div className="info-section">
                <h3>Contact</h3>
                <p>📞 {vendor.phoneNumber}</p>
              </div>
            )}

            {vendor.licenseNumber && (
              <div className="info-section">
                <h3>License Information</h3>
                <p>License: {vendor.licenseNumber}</p>
                {vendor.licenseExpiry && (
                  <p>Valid until: {new Date(vendor.licenseExpiry).toLocaleDateString()}</p>
                )}
              </div>
            )}
          </div>

          <div className="vendor-actions">
            <button 
              onClick={() => window.history.back()} 
              className="btn btn-outline"
            >
              Go Back
            </button>
          </div>
        </div>

        {/* Similar vendors section */}
        <div className="similar-vendors">
          <h3>Other Food Trucks in {vendor.operatingRegion}</h3>
          <p>Discover more amazing food trucks in your area</p>
          <button 
            onClick={() => navigate(`/vendors?region=${vendor.operatingRegion}`)} 
            className="btn btn-primary"
          >
            Browse {vendor.operatingRegion} Vendors
          </button>
        </div>
      </div>
    </div>
  );
};

export default VendorDetails;
